s/        \/\/ Hex only: the value is written into a style attribute, where Mustache escaping\n        \/\/ does not protect\.\n        if \(preg_match\('\/\^#\?\(\[A-Fa-f0-9\]\{6\}\|\[A-Fa-f0-9\]\{3\}\)\$\/', \$value\)\) \{\n            if \(\$value\[0\] !== '#'\) \{\n                \$value = '#' \. \$value;\n            \}\n            return \$value;\n        \}\n\n        return null;/        return \$value;/;
